<template><div class="app-container"><el-card><div slot="header">我的持仓</div><el-form :inline="true" :model="form"><el-form-item label="账户总资产"><el-input v-model="assets"/><el-button @click="save">保存</el-button></el-form-item><el-form-item label="代码"><el-input v-model="form.stockCode"/></el-form-item><el-form-item label="成本价"><el-input v-model="form.costPrice"/></el-form-item><el-form-item label="数量"><el-input v-model="form.quantity"/></el-form-item><el-button type="primary" @click="add">新增持仓</el-button></el-form><el-table :data="rows"><el-table-column prop="stockCode" label="代码"/><el-table-column prop="costPrice" label="成本"/><el-table-column prop="quantity" label="数量"/><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="analyze(s.row,false)">分析</el-button><el-button type="text" @click="analyze(s.row,true)">AI分析</el-button></template></el-table-column></el-table><el-card v-if="result"><h3>{{result.stock.name}} 客观指标</h3><p>开高低收：{{result.stock.openPrice}} / {{result.stock.high}} / {{result.stock.low}} / {{result.stock.currentPrice}}</p><p>MA5/MA20：{{result.stock.ma5}} / {{result.stock.ma20}}；趋势：{{result.trendDesc}}；信号：{{result.signal.description}}</p><p>成交量：{{result.stock.volume}}；所属板块趋势：暂未接入</p><p v-if="result.holding">成本金额 {{result.holding.costAmount}}，市值 {{result.holding.marketValue}}，浮盈亏 {{result.holding.profitAmount}}，浮盈亏率 {{result.holding.profitPct}}%，持仓比例 {{result.holding.positionPct || '未设置'}}%</p><div v-if="ai"><h3>DeepSeek 三步分析</h3><p>{{result.aiAdvice}}</p><p>{{result.aiReason}}</p></div></el-card></el-card></div></template>
<script>import {listPosition,addPosition,account,saveAccount,analyzePosition} from '@/api/stock/position';export default{name:'StockPosition',data(){return{rows:[],assets:'',form:{stockCode:'',costPrice:'',quantity:''},result:null,ai:false}},created(){this.load()},methods:{load(){listPosition().then(r=>this.rows=r.data);account().then(r=>this.assets=r.data&&r.data.totalAssets||'')},save(){saveAccount({totalAssets:this.assets}).then(()=>this.$modal.msgSuccess('已保存'))},add(){addPosition(this.form).then(()=>{this.load();this.$modal.msgSuccess('已新增')})},analyze(row,ai){analyzePosition(row.positionId,ai).then(r=>{this.result=r.data;this.ai=ai})}}}</script>
